import random
random.seed(42)

class Node:
    def __init__(self, score, member, level):
        self.score = score; self.member = member
        self.forward = [None] * level

class SkipList:
    def __init__(self):
        self.maxlevel = 16
        self.head = Node(0, "", self.maxlevel)
        self.level = 1; self.length = 0
    def random_level(self):
        lvl = 1
        while random.random() < 0.25 and lvl < self.maxlevel:
            lvl += 1
        return lvl
    def insert(self, score, member):
        update = [None] * self.maxlevel
        x = self.head
        for i in range(self.level - 1, -1, -1):
            while x.forward[i] and (x.forward[i].score < score or
                                    (x.forward[i].score == score and x.forward[i].member < member)):
                x = x.forward[i]
            update[i] = x
        x = x.forward[0]
        if x and x.score == score and x.member == member:
            x.score = score; return
        lvl = self.random_level()
        if lvl > self.level:
            for i in range(self.level, lvl):
                update[i] = self.head
            self.level = lvl
        n = Node(score, member, lvl)
        for i in range(lvl):
            n.forward[i] = update[i].forward[i]
            update[i].forward[i] = n
        self.length += 1
    def range_by_score(self, lo, hi):
        res = []
        x = self.head.forward[0]
        while x:
            if lo <= x.score <= hi:
                res.append((x.score, x.member))
            if x.score > hi:
                break
            x = x.forward[0]
        return res

sl = SkipList()
for s, m in [(1, "a"), (3, "c"), (2, "b"), (5, "e"), (4, "d")]:
    sl.insert(s, m)
print("length=%d maxlevel_used=%d" % (sl.length, sl.level))
print("range [2,4] =", sl.range_by_score(2, 4))
